Suporte de transmissão a parâmetros de saída BLOB
Este tópico contém um exemplo que mostra o suporte de transmissão a parâmetros de saída BLOB, que associa parâmetros de saída BLOB como ISequentialStreams.
Você pode ser bloqueado em parâmetros de saída em IMultipleResults::GetResult, recebendo o valor de retorno DB_E_OBJECTOPEN. O chamador deve verificar se há parâmetros BLOB pendentes e lê-los completamente ou liberá-los.
Exemplo
Código
// blob_out_param.cpp
// compile with: /EHsc ole32.lib oleaut32.lib
#define UNICODE
#define DBINITCONSTANTS
#define INITGUID
#define OLEDBVER 0x0250
#include <windows.h>
// Change the following to match your server and test database,
// and also the 'use' statement in the setup SQL that follows
const WCHAR* g_wchServerName = L".";
const WCHAR* g_wchDBName = L"TestDB";
const WCHAR* g_wchSecurity = L"SSPI";
/*
// Execute the following before running the program
use TestDB
go
drop proc Scenario1
go
drop table tScenario1
go
create table tScenario1 (c1 int, c2 varchar(20))
go
insert into tScenario1 values (1, 'abcdefgh')
insert into tScenario1 values (2, 'ijklm')
insert into tScenario1 values (3, 'nopqr')
insert into tScenario1 values (4, 'stuvwxyz')
go
create proc Scenario1 @p1 int output, @p2 varchar(max) output, @p3 xml output, @p4 varchar(20) output
as
begin
set @p1 = @p1 + 5
set @p2 = replicate(convert(varchar(max), 'a'), 10000)
set @p3 = '<tag1>Some text</tag1>'
set @p4 = '@p4 varchar(20)'
select * from tScenario1
return datalength(@p2)
end
go
------------------------- TESTING CODE -------------------------
declare @v1 int
set @v1 = 16
declare @v2 varchar(max)
declare @v3 xml
declare @v4 varchar(20)
declare @ret_val int
exec @ret_val = Scenario1 @v1 output, @v2 output, @v3 output, @v4 output
print @v1
print @v2
print convert(nchar, @v3)
print @v4
print @ret_val
go
*/
#include <stdio.h>
#include <stddef.h>
#include <iostream>
#include <oledb.h>
#include <oledberr.h>
#include <sqlncli.h>
#include <iostream>
#include <tchar.h>
using namespace std;
#define CHKHR_GOTO(hr, lblExit, szMsg) \
do \
{ \
if (FAILED(hr)) \
{ \
cout << szMsg << endl; \
goto lblExit; \
} \
} \
while (0)
#define RELEASE_ITF(pItf) \
if (pItf) \
{ \
pItf->Release(); \
pItf = NULL; \
}
#define INIT_BINDINGS(acDBBinding, nBindings) \
for(int uIndex = 0; uIndex < nBindings; uIndex++) { \
acDBBinding[uIndex].iOrdinal = uIndex + 1; \
acDBBinding[uIndex].obLength = 0; \
acDBBinding[uIndex].obStatus = 0; \
acDBBinding[uIndex].pTypeInfo = NULL; \
acDBBinding[uIndex].pObject = NULL; \
acDBBinding[uIndex].pBindExt = NULL; \
acDBBinding[uIndex].dwPart = DBPART_VALUE; \
acDBBinding[uIndex].dwMemOwner = DBMEMOWNER_CLIENTOWNED; \
acDBBinding[uIndex].dwFlags = 0; \
acDBBinding[uIndex].bScale = 0; \
}
IDBInitialize* pIDBInitialize = NULL;
HRESULT Connect(ICommandText** ppICommandText) {
HRESULT hr;
IDBProperties* pIDBProperties = NULL;
IDBCreateSession* pIDBCreateSession = NULL;
IDBCreateCommand* pIDBCreateCommand = NULL;
ICommandText* pICommandText = NULL;
const ULONG nInitProps = 3;
const ULONG nPropSet = 1;
DBPROP InitProperties[nInitProps];
DBPROPSET InitPropSet [nPropSet];
*ppICommandText = NULL;
hr = CoInitialize(NULL);
CHKHR_GOTO(hr, _ExitConnect, "Unable to Initialize COM.");
hr = CoCreateInstance(CLSID_SQLNCLI10, NULL, CLSCTX_INPROC_SERVER, IID_IDBInitialize, (void **) &pIDBInitialize);
CHKHR_GOTO(hr, _ExitConnect, "Unable to Load SQLNCLI10.");
for(ULONG uIndexProp = 0; uIndexProp < nInitProps; uIndexProp++) {
VariantInit(&InitProperties[uIndexProp].vValue);
InitProperties[uIndexProp].vValue.vt = VT_BSTR;
InitProperties[uIndexProp].dwOptions = DBPROPOPTIONS_REQUIRED;
InitProperties[uIndexProp].colid = DB_NULLID;
}
InitProperties[0].dwPropertyID = DBPROP_INIT_DATASOURCE;
InitProperties[0].vValue.bstrVal = SysAllocString(g_wchServerName);
InitProperties[1].dwPropertyID = DBPROP_INIT_CATALOG;
InitProperties[1].vValue.bstrVal = SysAllocString(g_wchDBName);
InitProperties[2].dwPropertyID = DBPROP_AUTH_INTEGRATED;
InitProperties[2].vValue.bstrVal = SysAllocString(g_wchSecurity);
InitPropSet[0].guidPropertySet = DBPROPSET_DBINIT;
InitPropSet[0].cProperties = 3;
InitPropSet[0].rgProperties = InitProperties;
hr = pIDBInitialize->QueryInterface(IID_IDBProperties, (void **)&pIDBProperties);
CHKHR_GOTO(hr, _ExitConnect, "Failed to obtain IDBProperties interface.");
hr = pIDBProperties->SetProperties(nPropSet, InitPropSet);
CHKHR_GOTO(hr, _ExitConnect, "Failed to Set Initialization properties.");
hr = pIDBInitialize->Initialize();
CHKHR_GOTO(hr, _ExitConnect, "Failed to Connect to the Server.");
//Create a new activity from the data source object.
hr = pIDBInitialize->QueryInterface(IID_IDBCreateSession, (void**) &pIDBCreateSession);
CHKHR_GOTO(hr, _ExitConnect, "Failed to obtain IDBCreateSession interface.");
hr = pIDBCreateSession->CreateSession(NULL, IID_IDBCreateCommand, (IUnknown**) &pIDBCreateCommand);
CHKHR_GOTO(hr, _ExitConnect, "Failed to create a new Session.");
hr = pIDBCreateCommand->CreateCommand(NULL, IID_ICommandText, (IUnknown**) &pICommandText);
CHKHR_GOTO(hr, _ExitConnect, "Failed to create a new Command.");
*ppICommandText = pICommandText;
_ExitConnect:
RELEASE_ITF(pIDBCreateCommand);
for(ULONG uIndexProp = 0; uIndexProp < nInitProps; uIndexProp++)
VariantClear(&InitProperties[uIndexProp].vValue);
RELEASE_ITF(pIDBProperties);
return hr;
}
HRESULT DisConnect() {
HRESULT hr = S_OK;
if (pIDBInitialize)
hr = pIDBInitialize->Uninitialize();
RELEASE_ITF(pIDBInitialize);
return hr;
}
int main() {
HRESULT hr;
const WCHAR* g_wchCmdString = L"{? = call Scenario1 ( ?, ?, ?, ?)};{? = call Scenario1 ( ?, ?, ?, ?)}";
ICommandText* pICommandText = NULL;
IAccessor* pIAccessor = NULL;
HACCESSOR hAccessor = NULL;
IRowset* pIRowset = NULL;
IMultipleResults* pIMultipleResults = NULL;
ISequentialStream* pIStream = NULL;
const ULONG nParams = 10;
ULONG uIndex = 0;
DBBINDING acDBBinding [nParams];
DBBINDSTATUS acDBBindStatus[nParams];
typedef struct tagSPROCPARAMS {
long lReturnValue;
long lInt;
IUnknown* streamVarcharMax;
IUnknown* streamXML;
char chVarChar[21];
long lReturnValue2;
long lInt2;
IUnknown* streamVarcharMax2;
IUnknown* streamXML2;
char chVarChar2[21];
} SPROCPARAMS;
SPROCPARAMS sprocparams[] = {{ 6, 17, NULL, NULL, "", 4, 20, NULL, NULL, ""},{ 5, 23, NULL, NULL, "", 7, 11, NULL, NULL, ""}};
const int nBlobBindingIndexes = 8;
IUnknown** ppBoundBlobs[nBlobBindingIndexes];
int idxBlobBindingCurrent = 0;
ppBoundBlobs[0] = &(sprocparams[0].streamVarcharMax);
ppBoundBlobs[1] = &(sprocparams[0].streamXML);
ppBoundBlobs[2] = &(sprocparams[0].streamVarcharMax2);
ppBoundBlobs[3] = &(sprocparams[0].streamXML2);
ppBoundBlobs[4] = &(sprocparams[1].streamVarcharMax);
ppBoundBlobs[5] = &(sprocparams[1].streamXML);
ppBoundBlobs[6] = &(sprocparams[1].streamVarcharMax2);
ppBoundBlobs[7] = &(sprocparams[1].streamXML2);
LONG cNumRows;
DBPARAMS Params;
hr = Connect(&pICommandText);
if (FAILED(hr))
goto _Exit;
hr = pICommandText->SetCommandText(DBGUID_DBSQL, g_wchCmdString);
CHKHR_GOTO(hr, _Exit, "Failed to Set Command Text.");
hr = pICommandText->QueryInterface(IID_IAccessor, (void**)&pIAccessor);
CHKHR_GOTO(hr, _Exit, "Failed to get IAccessor interface on Command object.");
INIT_BINDINGS(acDBBinding, nParams);
acDBBinding[0].obValue = offsetof(SPROCPARAMS, lReturnValue);
acDBBinding[0].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[0].cbMaxLen = sizeof(sprocparams[0].lReturnValue);
acDBBinding[0].wType = DBTYPE_I4;
acDBBinding[0].bPrecision = 11;
acDBBinding[1].obValue = offsetof(SPROCPARAMS, lInt);
acDBBinding[1].eParamIO = DBPARAMIO_INPUT | DBPARAMIO_OUTPUT;
acDBBinding[1].cbMaxLen = sizeof(sprocparams[0].lInt);
acDBBinding[1].wType = DBTYPE_I4;
acDBBinding[1].bPrecision = 11;
acDBBinding[2].obValue = offsetof(SPROCPARAMS, streamVarcharMax);
acDBBinding[2].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[2].cbMaxLen = sizeof(sprocparams[0].streamVarcharMax);
acDBBinding[2].wType = DBTYPE_IUNKNOWN;
acDBBinding[2].pObject = new DBOBJECT;
acDBBinding[2].pObject->dwFlags = STGM_READ;
acDBBinding[2].pObject->iid = IID_ISequentialStream;
acDBBinding[2].bPrecision = 255;
acDBBinding[3].obValue = offsetof(SPROCPARAMS, streamXML);
acDBBinding[3].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[3].cbMaxLen = sizeof(sprocparams[0].streamXML);
acDBBinding[3].wType = DBTYPE_IUNKNOWN;
acDBBinding[3].pObject = new DBOBJECT;
acDBBinding[3].pObject->dwFlags = STGM_READ;
acDBBinding[3].pObject->iid = IID_ISequentialStream;
acDBBinding[3].bPrecision = 255;
acDBBinding[4].obValue = offsetof(SPROCPARAMS, chVarChar);
acDBBinding[4].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[4].cbMaxLen = sizeof(sprocparams[0].chVarChar);
acDBBinding[4].wType = DBTYPE_STR;
acDBBinding[4].bPrecision = 255;
acDBBinding[5].obValue = offsetof(SPROCPARAMS, lReturnValue2);
acDBBinding[5].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[5].cbMaxLen = sizeof(sprocparams[0].lReturnValue2);
acDBBinding[5].wType = DBTYPE_I4;
acDBBinding[5].bPrecision = 11;
acDBBinding[6].obValue = offsetof(SPROCPARAMS, lInt2);
acDBBinding[6].eParamIO = DBPARAMIO_INPUT | DBPARAMIO_OUTPUT;
acDBBinding[6].cbMaxLen = sizeof(sprocparams[0].lInt2);
acDBBinding[6].wType = DBTYPE_I4;
acDBBinding[6].bPrecision = 11;
acDBBinding[7].obValue = offsetof(SPROCPARAMS, streamVarcharMax2);
acDBBinding[7].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[7].cbMaxLen = sizeof(sprocparams[0].streamVarcharMax2);
acDBBinding[7].wType = DBTYPE_IUNKNOWN;
acDBBinding[7].pObject = new DBOBJECT;
acDBBinding[7].pObject->dwFlags = STGM_READ;
acDBBinding[7].pObject->iid = IID_ISequentialStream;
acDBBinding[7].bPrecision = 255;
acDBBinding[8].obValue = offsetof(SPROCPARAMS, streamXML2);
acDBBinding[8].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[8].cbMaxLen = sizeof(sprocparams[0].streamXML2);
acDBBinding[8].wType = DBTYPE_IUNKNOWN;
acDBBinding[8].pObject = new DBOBJECT;
acDBBinding[8].pObject->dwFlags = STGM_READ;
acDBBinding[8].pObject->iid = IID_ISequentialStream;
acDBBinding[8].bPrecision = 255;
acDBBinding[9].obValue = offsetof(SPROCPARAMS, chVarChar2);
acDBBinding[9].eParamIO = DBPARAMIO_OUTPUT;
acDBBinding[9].cbMaxLen = sizeof(sprocparams[0].chVarChar2);
acDBBinding[9].wType = DBTYPE_STR;
acDBBinding[9].bPrecision = 255;
hr = pIAccessor->CreateAccessor(
DBACCESSOR_PARAMETERDATA,
nParams,
acDBBinding,
sizeof(SPROCPARAMS),
&hAccessor,
acDBBindStatus);
CHKHR_GOTO(hr, _Exit, "Failed to Create Accessor for the defined parameters.");
Params.pData = &sprocparams;
Params.cParamSets = sizeof(sprocparams)/sizeof(SPROCPARAMS);
Params.hAccessor = hAccessor;
hr = pICommandText->Execute(NULL, IID_IMultipleResults, &Params, &cNumRows, (IUnknown**)&pIMultipleResults);
CHKHR_GOTO(hr, _Exit, "Failed to Execute Command.");
cout << "Command executed successfully, retrieving results." << endl;
idxBlobBindingCurrent = 0;
if (pIMultipleResults) {
for (;;) {
hr = pIMultipleResults->GetResult(NULL, 0, IID_IRowset, NULL, (IUnknown**)&pIRowset);
if (hr == DB_S_NORESULT) {
cout << "All results processed." << endl;
break;
}
if (FAILED(hr)) {
// In this case, user has open rowset or open blobs
if (hr == DB_E_OBJECTOPEN) {
IUnknown* pIUnkCurrent = *ppBoundBlobs[idxBlobBindingCurrent];
if (pIUnkCurrent) {
hr = pIUnkCurrent->QueryInterface(IID_ISequentialStream, (void**)&pIStream);
if (FAILED(hr)) {
cout << "Failed to get a stream object. " << endl;
goto _Exit;
}
RELEASE_ITF(pIUnkCurrent);
// Display the data
char chBuff [51];
wchar_t wchBuff[51];
ULONG cbRead = 0;
do {
if (idxBlobBindingCurrent % 2) {
hr = pIStream->Read(wchBuff, 50 * sizeof(wchar_t), &cbRead);
if (hr == E_UNEXPECTED)
break;
wchBuff[cbRead / 2] = 0;
printf_s("%S", wchBuff[0] == 0xFEFF ? wchBuff+1 : wchBuff);
if (hr == S_FALSE || cbRead < 50 * sizeof(wchar_t)) {
cout << endl;
RELEASE_ITF(pIStream);
break;
}
}
else {
hr = pIStream->Read(chBuff, 50, &cbRead);
if (hr == E_UNEXPECTED)
break;
chBuff[cbRead] = 0;
printf_s("%s", chBuff);
if (hr == S_FALSE || cbRead < 50) {
cout << endl;
RELEASE_ITF(pIStream);
break;
}
}
} while (SUCCEEDED(hr));
if (FAILED(hr) && hr != E_UNEXPECTED) {
cout << "Stream data read failed." << endl;
goto _Exit;
}
idxBlobBindingCurrent++;
continue;
}
}
else {
cout << "GetResult failed with unknown error." << endl;
break;
}
}
else {
if (pIRowset) {
DBCOUNTITEM cRowsObtained;
DBCOUNTITEM cRowsTotal = 0;
HROW hRow[1];
HROW* phRow = hRow;
do {
hr = pIRowset->GetNextRows(0, 0, 1, &cRowsObtained, &phRow);
cRowsTotal += cRowsObtained;
pIRowset->ReleaseRows(cRowsObtained, hRow, NULL, NULL, NULL);
} while (SUCCEEDED(hr) && hr != DB_S_ENDOFROWSET);
cout << "Total number of Rows: " << cRowsTotal << endl;
}
RELEASE_ITF(pIRowset);
}
}
}
// Now display the rest of parameters
printf_s(" lReturnValue : %d\n", sprocparams[0].lReturnValue);
printf_s(" lInt : %d\n", sprocparams[0].lInt);
printf_s(" chVarChar : %s\n", sprocparams[0].chVarChar);
printf_s(" lReturnValue : %d\n", sprocparams[0].lReturnValue2);
printf_s(" lInt : %d\n", sprocparams[0].lInt2);
printf_s(" chVarChar : %s\n", sprocparams[0].chVarChar);
printf_s(" lReturnValue : %d\n", sprocparams[1].lReturnValue);
printf_s(" lInt : %d\n", sprocparams[1].lInt);
printf_s(" chVarChar : %s\n", sprocparams[1].chVarChar);
printf_s(" lReturnValue : %d\n", sprocparams[1].lReturnValue2);
printf_s(" lInt : %d\n", sprocparams[1].lInt2);
printf_s(" chVarChar : %s\n", sprocparams[1].chVarChar);
_Exit:
RELEASE_ITF(pIStream);
RELEASE_ITF(pIRowset);
RELEASE_ITF(pIMultipleResults);
if (pIAccessor) {
pIAccessor->ReleaseAccessor(hAccessor, NULL);
RELEASE_ITF(pIAccessor);
}
RELEASE_ITF(pICommandText);
DisConnect();
}

ReportingService2005.ListExtensions(ExtensionTypeEnum) Método
Definição
Importante
Algumas informações se referem a produtos de pré-lançamento que podem ser substancialmente modificados antes do lançamento. A Microsoft não oferece garantias, expressas ou implícitas, das informações aqui fornecidas.
Retorna uma lista de extensões configuradas para um determinado tipo de extensão.
public:
cli::array <ReportService2005::Extension ^> ^ ListExtensions(ReportService2005::ExtensionTypeEnum ExtensionType);
public ReportService2005.Extension[] ListExtensions(ReportService2005.ExtensionTypeEnum ExtensionType);
member this.ListExtensions : ReportService2005.ExtensionTypeEnum -> ReportService2005.Extension[]
Public Function ListExtensions (ExtensionType As ExtensionTypeEnum) As Extension()
Parâmetros
- ExtensionType
- ExtensionTypeEnum
O tipo de extensão para o qual listar as extensões configuradas. Os valores disponíveis são Delivery
, Render
, Data
ou All
. Para obter mais informações, consulte ExtensionTypeEnum.
Retornos
Retorna uma matriz de objetos Extension que contém as extensões disponíveis.
Exemplos
Para compilar o exemplo de código a seguir, você deve referenciar o Reporting Services WSDL e importar determinados namespaces. Para obter mais informações, consulte Compilando e executando exemplos de código. O exemplo de código a seguir recupera uma lista de todas as extensões de processamento de dados com suporte instaladas atualmente no servidor de relatório:
Imports System
Imports System.Web.Services.Protocols
Class Sample
Public Shared Sub Main()
Dim rs As New ReportingService2005()
rs.Credentials = System.Net.CredentialCache.DefaultCredentials
' Set the base Web service URL of the source server
rs.Url = "http://servername/reportserver/reportservice.asmx"
Dim extensions As Extension() = Nothing
' Retrieve a list of all supported data processing extensions.
Try
extensions = rs.ListExtensions(ExtensionTypeEnum.Data)
If Not (extensions Is Nothing) Then
Dim extension As Extension
For Each extension In extensions
Console.WriteLine("Name: {0}", extension.Name)
Next extension
End If
Catch e As SoapException
Console.WriteLine(e.Detail.OuterXml)
End Try
End Sub 'Main
End Class 'Sample
using System;
using System.Web.Services.Protocols;
class Sample
{
public static void Main()
{
ReportingService2005 rs = new ReportingService2005();
rs.Credentials = System.Net.CredentialCache.DefaultCredentials;
Extension[] extensions = null;
// Retrieve a list of all supported data processing extensions.
try
{
extensions = rs.ListExtensions(ExtensionTypeEnum.Data);
if (extensions != null)
{
foreach (Extension extension in extensions)
{
Console.WriteLine("Name: {0}", extension.Name);
}
}
}
catch (SoapException e)
{
Console.WriteLine(e.Detail.OuterXml);
}
}
}
Comentários
A tabela a seguir mostra o cabeçalho e as informações de permissão sobre esta operação.
| Cabeçalhos SOAP | (Out) ServerInfoHeaderValue |
| Permissões necessárias | Nenhum |

sp_articleview (Transact-SQL)
Cria a exibição que define o artigo publicado, quando uma tabela é filtrada verticalmente ou horizontalmente. Essa exibição é usada como a fonte filtrada de esquema e dados para as tabelas de destino. Somente artigos não assinados podem ser modificados por esse procedimento armazenado. Esse procedimento armazenado é executado no Publicador, no banco de dados de publicação.
Sintaxe
sp_articleview [ @publication = ] 'publication'
, [ @article = ] 'article'
[ , [ @view_name = ] 'view_name']
[ , [ @filter_clause = ] 'filter_clause']
[ , [ @change_active = ] change_active ]
[ , [ @force_invalidate_snapshot = ] force_invalidate_snapshot ]
[ , [ @force_reinit_subscription = ] force_reinit_subscription ]
[ , [ @publisher = ] 'publisher' ]
[ , [ @refreshsynctranprocs = ] refreshsynctranprocs ]
[ , [ @internal = ] internal ]
Argumentos
[ @publication=] 'publication'
É o nome da publicação que contém o artigo. publication é sysname, sem padrão.[ @article=] 'article'
É o nome do artigo. article é sysname, sem padrão.[ @view_name=] 'view_name'
É o nome da exibição que define o artigo publicado. view_name é nvarchar (386), com um padrão NULL.[ @filter_clause=] 'filter_clause'
É uma cláusula de restrição (WHERE) que define um filtro horizontal. Ao inserir a cláusula de restrição, omita a palavra-chave WHERE. filter_clause é ntext, com um padrão NULL.[ @ change_active = ] change_active
Permite modificar as colunas em publicações que têm assinatura. change_active é um int, com um padrão 0. Se for 0, as colunas não serão alteradas . Se for 1, as exibições poderão ser criadas ou recriadas em artigos ativos que têm assinaturas.[ @force_invalidate_snapshot = ] force_invalidate_snapshot
Reconhece que a ação tomada por esse procedimento armazenado pode invalidar um instantâneo existente. force_invalidate_snapshot é um bit, com um padrão 0.0 especifica que as alterações no artigo não invalidam o instantâneo. Se o procedimento armazenado detectar que a alteração requer um novo instantâneo, ocorrerá um erro e nenhuma alteração será feita.
1 especifica que as alterações no artigo de mesclagem podem invalidar o instantâneo e se houver assinaturas existentes que exigem um novo instantâneo, dará permissão para que o instantâneo existente seja marcado como obsoleto e um novo instantâneo seja gerado.
[ @force_reinit_subscription = ] force_reinit_subscription
Reconhece que a ação tomada por esse procedimento armazenado pode requerer que as assinaturas existentes sejam reiniciadas. force_reinit_subscription é um bit, com um padrão 0.0 especifica que as alterações no artigo não fazem com que a assinatura seja reiniciada. Se o procedimento armazenado detectar que a alteração irá requerer que as assinaturas existentes sejam reiniciadas, ocorrerá um erro e nenhuma alteração será feita.
1 especifica que alterações no artigo causam a reinicialização de assinaturas existentes e dão permissão para que a assinatura seja reiniciada.
[ @publisher= ] 'publisher'
Especifica um Publicador não-MicrosoftSQL Server. publisher é sysname, com um padrão NULL.Observação publisher não deve ser usado ao publicar de um Editor SQL Server.
[ @refreshsynctranprocs = ] refreshsynctranprocs
Se os procedimentos armazenados usados para sincronizar replicações serão automaticamente recriados. refreshsynctranprocs é bit, com um padrão 1.1 significa que os procedimentos armazenados são recriados.
0 significa que os procedimentos armazenados não são recriados.
[ @internal= ] internal
Identificado apenas para fins informativos. Não há suporte. A compatibilidade futura não está garantida.
Valores de código de retorno
0 (êxito) ou 1 (falha)
Comentários
sp_articleview cria a definição que cria o artigo publicado e insere a ID dessa exibição na coluna sync_objid da tabela sysarticles (Transact-SQL) e insere o texto da cláusula de restrição na coluna filter_clause. Se todas as colunas forem replicadas e não houver filter_clause, sync_objid na tabela sysarticles (Transact-SQL) será definida como a ID da tabela base e o uso de sp_articleview não será necessário.
Para publicar uma tabela filtrada verticalmente (ou seja, para filtrar colunas) execute primeiro sp_addarticle sem nenhum parâmetro sync_object, execute sp_articlecolumn (Transact-SQL) uma vez para cada coluna a ser replicada (definindo o filtro vertical) e, então, execute sp_articleview para criar a exibição que define o artigo publicado.
Para publicar uma tabela horizontalmente filtrada (ou seja, para filtrar linhas), execute sp_addarticle (Transact-SQL) sem nenhum parâmetro filter. Execute sp_articlefilter (Transact-SQL), fornecendo todos os parâmetros, incluindo filter_clause. Depois execute sp_articleview, fornecendo todos os parâmetros incluindo o filter_clause idêntico.
Para publicar uma tabela filtrada verticalmente e horizontalmente, execute sp_addarticle (Transact-SQL) sem os parâmetros sync_object ou filter. Execute sp_articlecolumn (Transact-SQL) uma vez para cada coluna a ser replicada e, então, execute sp_articlefilter (Transact-SQL) e sp_articleview.
Se o artigo já tiver uma exibição que define o artigo publicado, sp_articleview descartará a exibição existente e criará uma nova exibição automaticamente. Se a exibição foi criada manualmente (type em sysarticles (Transact-SQL) é 5), a exibição existente não será descartada.
Se você criou um procedimento armazenado de filtro personalizado e uma exibição que define o artigo publicado manualmente, não execute sp_articleview. Em vez disso, forneça esses como os parâmetros filter e sync_object para sp_addarticle (Transact-SQL), junto com o valor type apropriado.
Exemplo
DECLARE @publication AS sysname;
DECLARE @table AS sysname;
DECLARE @filterclause AS nvarchar(500);
DECLARE @filtername AS nvarchar(386);
DECLARE @schemaowner AS sysname;
SET @publication = N'AdvWorksProductTran';
SET @table = N'Product';
SET @filterclause = N'[DiscontinuedDate] IS NULL';
SET @filtername = N'filter_out_discontinued';
SET @schemaowner = N'Production';
-- Add a horizontally and vertically filtered article for the Product table.
-- Manually set @schema_option to ensure that the Production schema
-- is generated at the Subscriber (0x8000000).
EXEC sp_addarticle
@publication = @publication,
@article = @table,
@source_object = @table,
@source_owner = @schemaowner,
@schema_option = 0x80030F3,
@vertical_partition = N'true',
@type = N'logbased',
@filter_clause = @filterclause;
-- (Optional) Manually call the stored procedure to create the
-- horizontal filtering stored procedure. Since the type is
-- 'logbased', this stored procedures is executed automatically.
EXEC sp_articlefilter
@publication = @publication,
@article = @table,
@filter_clause = @filterclause,
@filter_name = @filtername;
-- Add all columns to the article.
EXEC sp_articlecolumn
@publication = @publication,
@article = @table;
-- Remove the DaysToManufacture column from the article
EXEC sp_articlecolumn
@publication = @publication,
@article = @table,
@column = N'DaysToManufacture',
@operation = N'drop';
-- (Optional) Manually call the stored procedure to create the
-- vertical filtering view. Since the type is 'logbased',
-- this stored procedures is executed automatically.
EXEC sp_articleview
@publication = @publication,
@article = @table,
@filter_clause = @filterclause;
GO
Permissões
Somente membros da função de servidor fixa sysadmin ou da função de banco de dados fixa db_owner podem executar sp_articleview.
