#define COPYBUFFERSIZE 4096
BOOL copyFileContents (HANDLE srcHandle, HANDLE dstHandle) {
BYTE buffer[COPYBUFFERSIZE];
DWORD bytesRead, bytesWritten;
BOOL r;
do {
r = ReadFile(srcHandle, buffer, COPYBUFFERSIZE, &bytesRead,NULL);
if (bytesRead == 0) {
return r;
}
r = WriteFile(dstHandle, buffer, bytesRead, &bytesWritten, NULL);
if (bytesWritten == 0) {
return r;
}
} while (TRUE);
}
BOOL copyFileToSql(LPCWSTR srcFilePath, LPCWSTR dstFilePath, LPBYTE transactionToken, SQLINTEGER cbTransactionToken) {
BOOL r;
HANDLE srcHandle, dstHandle;
unsigned int NtStatus;
srcHandle = CreateFile(
srcFilePath,
GENERIC_READ,
FILE_SHARE_READ,
NULL,
OPEN_EXISTING,
FILE_FLAG_SEQUENTIAL_SCAN,
NULL);
if (srcHandle == INVALID_HANDLE_VALUE) {
return FALSE;
}
dstHandle = OpenSqlFilestream(
dstFilePath,
Write,
0,
transactionToken,
cbTransactionToken,
0);
if (dstHandle == INVALID_HANDLE_VALUE) {
NtStatus = GetLastError();
r = CloseHandle(srcHandle);
return FALSE;
}
//copy file
r = copyFileContents(srcHandle, dstHandle);
CloseHandle(srcHandle);
CloseHandle(dstHandle);
return r;
}
BOOL copyFileFromSql(LPCWSTR srcFilePath, LPCWSTR dstFilePath, LPBYTE transactionToken, SQLINTEGER cbTransactionToken) {
BOOL r;
HANDLE srcHandle, dstHandle;
unsigned int NtStatus;
srcHandle = OpenSqlFilestream(
srcFilePath,
Read,
0,
transactionToken,
cbTransactionToken,
0);
if (srcHandle == INVALID_HANDLE_VALUE) {
return FALSE;
}
dstHandle = CreateFile(
dstFilePath,
GENERIC_WRITE,
0,
NULL,
OPEN_ALWAYS,
FILE_ATTRIBUTE_NORMAL,
NULL);
if (dstHandle == INVALID_HANDLE_VALUE) {
CloseHandle(srcHandle);
return FALSE;
}
r = copyFileContents(srcHandle, dstHandle);
CloseHandle(srcHandle);
CloseHandle(dstHandle);
return r;
}

Usando System.Transactions
O namespace System.Transactions é novo na versão 2.0 do Microsoft.NET Framework. Ele fornece uma nova estrutura de transação que é totalmente integrada com o ADO.NET e a integração CLR (Common Language Runtime) do SQL Server. Uma classe System.Transactions.TransactionScope torna um bloco de código transacional inscrevendo implicitamente conexões em uma transação distribuída. Chame o método Complete no final do bloco de código marcado pelo TransactionScope. O método Dispose será invocado quando a execução do programa deixar um bloco de código, fazendo a transação ser descontinuada se o método Complete não for chamado. Se tiver sido lançada uma exceção que faz o código deixar o escopo, a transação será considerada descontinuada.
É recomendável utilizar um bloco using para assegurar que o método Dispose seja chamado no objeto TransactionScope ao sair do bloco using. Uma falha ao confirmar ou reverter transações pendentes pode diminuir muito o desempenho, pois o tempo limite padrão para o TransactionScope é de um minuto. Se você não usar uma instrução using, deverá executar todo o trabalho em um bloco Try e chamar explicitamente o método Dispose no bloco Finally.
Se ocorrer uma exceção no TransactionScope, a transação será marcada como inconsistente e abandonada. Ela será revertida quando o TransactionScope for descartado. Se nenhuma exceção ocorrer, as transações participantes serão confirmadas.
TransactionScope deve ser usado somente quando são acessados gerenciadores de recursos externos ou fontes de dados locais e remotas. Isso porque TransactionScope sempre causa a elevação de transações, mesmo que esteja sendo usado apenas em uma conexão de contexto.
| Observação |
|---|
Por padrão, a classe TransactionScope cria uma transação com um System.Transactions.Transaction.IsolationLevel de Serializable. Dependendo do seu aplicativo, talvez você queira considerar abaixar o nível de isolamento para evitar uma contenção elevada em seu aplicativo. |
| Observação |
|---|
É recomendável executar apenas atualizações, inserções e exclusões em transações distribuídas em servidores remotos, pois isso consume recursos de banco de dados significativos. Caso a operação seja executada no servidor local, uma transação distribuída não será necessária e uma transação local será suficiente. Instruções SELECT podem bloquear recursos do banco de dados desnecessariamente e, em alguns cenários, pode ser necessário usar transações para seleções. Qualquer trabalho que não seja do banco de dados deve ser executado fora do escopo da transação, a menos que envolva outros gerenciadores de recursos transacionados. Apesar de uma exceção no escopo da transação evitar que a transação seja confirmada, a classe TransactionScope não tem provisão para reverter as alterações que seu código tenha feito fora do escopo da própria transação. Se precisar executar alguma ação ao reverter a ação, será necessário escrever sua própria implementação da interface System.Transactions.IEnlistmentNotification e inscrevê-la na transação explicitamente. |
Exemplo
Para trabalhar com System.Transactions, é necessário ter uma referência para o arquivo System.Transactions.dll.
O código a seguir demonstra como criar uma transação que pode ser elevada em duas instâncias diferentes do SQL Server. Essas instâncias são representadas por dois objetos System.Data.SqlClient.SqlConnection diferentes, que são quebrados em um bloco TransactionScope. O código cria o bloco TransactionScope com uma instrução using e abre a primeira conexão, que o inscreve automaticamente no TransactionScope. A transação é inscrita inicialmente como uma transação lightweight, não uma transação distribuída completa. O código presume a existência de uma lógica condicional (que foi omitida para ser breve). Ele abrirá a segunda conexão somente se for necessário, inscrevendo-o no TransactionScope. Quando a conexão é aberta, a transação é automaticamente elevada a uma transação distribuída completa. Então, o código invoca TransactionScope.Complete, que confirma a transação. O código dispõe das duas conexões ao sair das instruções using para as conexões. O método TransactionScope.Dispose para o TransactionScope é chamado automaticamente no encerramento do bloco using para o TransactionScope. Se uma exceção tiver sido lançada em qualquer ponto no bloco TransactionScope, Complete não será chamado e a transação distribuída será revertida quando o TransactionScope for descartado.
Visual Basic
Using transScope As New TransactionScope()
Using connection1 As New SqlConnection(connectString1)
' Opening connection1 automatically enlists it in the
' TransactionScope as a lightweight transaction.
connection1.Open()
' Do work in the first connection.
' Assumes conditional logic in place where the second
' connection will only be opened as needed.
Using connection2 As New SqlConnection(connectString2)
' Open the second connection, which enlists the
' second connection and promotes the transaction to
' a full distributed transaction.
connection2.Open()
' Do work in the second connection.
End Using
End Using
' Commit the transaction.
transScope.Complete()
End Using
C#
using (TransactionScope transScope = new TransactionScope())
{
using (SqlConnection connection1 = new
SqlConnection(connectString1))
{
// Opening connection1 automatically enlists it in the
// TransactionScope as a lightweight transaction.
connection1.Open();
// Do work in the first connection.
// Assumes conditional logic in place where the second
// connection will only be opened as needed.
using (SqlConnection connection2 = new
SqlConnection(connectString2))
{
// Open the second connection, which enlists the
// second connection and promotes the transaction to
// a full distributed transaction.
connection2.Open();
// Do work in the second connection.
}
}
// The Complete method commits the transaction.
transScope.Complete();
}

Como definir um Artigo (programação RMO)
Defina artigos de forma programada, usando RMO (Replication Management Objects). As classes de RMO usadas para definir um artigo dependem do tipo de publicação para a qual o artigo é definido.
Para definir artigos para instantâneo ou publicação transacional.
Crie uma conexão com o Publicador usando a classe ServerConnection.
Crie uma instância da classe TransArticle, defina a propriedade ConnectionContext (herdada de ReplicationObject) para a instância de ServerConnection na Etapa 1 e defina as seguintes propriedades:
Nome do artigo para Name.
Nome da publicação para PublicationName.
Nome do banco de dados de publicação para DatabaseName.
(Opcional) Se o artigo tiver um filtro de linha estático, especifique a cláusula de filtro para a propriedade FilterClause.
Chame o método Create.
(Opcional) Se o artigo tiver filtros de coluna:
Chame o método RemoveReplicatedColumns para remover colunas para o artigo. Passe uma matriz String dos nomes de colunas a serem removidas. Passe um valor null para remoção de todas as colunas.
Chame o método AddReplicatedColumns para adicionar colunas ao artigo. Passe uma matriz String de nomes de colunas a serem adicionadas. Passe um valor null a ser adicionado a todas as colunas.
Para definir artigos para uma publicação de mesclagem
Crie uma conexão com o Publicador usando a classe ServerConnection.
Crie uma instância da classe MergeArticle, defina a propriedade ConnectionContext (herdada de ReplicationObject) para a instância de ServerConnection na Etapa 1 e defina as seguintes propriedades:
Nome do artigo para Name.
Nome da publicação para PublicationName.
Nome do banco de dados de publicação para DatabaseName.
(Opcional) Se o artigo for filtrado horizontalmente, especifique a cláusula do filtro da linha para a propriedade FilterClause. Use essa propriedade para especificar um filtro de linha estático ou com parâmetros. Para obter mais informações, consulte Filtro de linha com parâmetros.
Chame o método Create.
(Opcional) Se o artigo tiver colunas filtradas:
Chame o método RemoveReplicatedColumns para remover colunas para o artigo. Passe uma matriz String dos nomes de colunas a serem removidas. Passe um valor null para remoção de todas as colunas.
Chame o método AddReplicatedColumns para adicionar colunas ao artigo. Passe uma matriz String de nomes de colunas a serem adicionadas. Passe um valor null a ser adicionado a todas as colunas.
(Opcional) Se o artigo precisar ser filtrado com base no filtro de linhas definido em outro artigo, crie uma instância da classe MergeJoinFilter para definir o filtro de união entre dois artigos. Em seguida, defina as seguintes propriedades:
O nome do artigo filho (da Etapa 2) sendo filtrado para a propriedade JoinArticleName.
Nome do artigo existente, filtrado, para o qual esse artigo está sendo unido para a propriedade ArticleName.
Nome do filtro de união para a propriedade FilterName.
Expressão que define a união para a propriedade JoinFilterClause.
Valor de JoinFilter para a propriedade FilterTypes.
Para obter mais informações, consulte Filtros de junção.
(Opcional) Chame o método AddMergeJoinFilter no objeto que representa o artigo filtrado da Etapa 2. Passe o objeto MergeJoinFilter da Etapa 5, para criar o filtro de união.
Exemplo
O exemplo a seguir adiciona um artigo com filtros de linha e de coluna para uma publicação transacional.
// Define the Publisher, publication, and article names.
string publisherName = publisherInstance;
string publicationName = "AdvWorksProductTran";
string publicationDbName = "AdventureWorks2008R2";
string articleName = "Product";
string schemaOwner = "Production";
TransArticle article;
// Create a connection to the Publisher.
ServerConnection conn = new ServerConnection(publisherName);
// Create a filtered transactional articles in the following steps:
// 1) Create the article with a horizontal filter clause.
// 2) Add columns to or remove columns from the article.
try
{
// Connect to the Publisher.
conn.Connect();
// Define a horizontally filtered, log-based table article.
article = new TransArticle();
article.ConnectionContext = conn;
article.Name = articleName;
article.DatabaseName = publicationDbName;
article.SourceObjectName = articleName;
article.SourceObjectOwner = schemaOwner;
article.PublicationName = publicationName;
article.Type = ArticleOptions.LogBased;
article.FilterClause = "DiscontinuedDate IS NULL";
// Ensure that we create the schema owner at the Subscriber.
article.SchemaOption |= CreationScriptOptions.Schema;
if (!article.IsExistingObject)
{
// Create the article.
article.Create();
}
else
{
throw new ApplicationException(String.Format(
"The article {0} already exists in publication {1}.",
articleName, publicationName));
}
// Create an array of column names to remove from the article.
String[] columns = new String[1];
columns[0] = "DaysToManufacture";
// Remove the column from the article.
article.RemoveReplicatedColumns(columns);
}
catch (Exception ex)
{
// Implement appropriate error handling here.
throw new ApplicationException("The article could not be created.", ex);
}
finally
{
conn.Disconnect();
}
